/* Copies the engine into the portal and writes the demo catalogue, so the
   static site has everything it needs. Run: npm run build:portal */
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');
const out = path.join(root, 'portal', 'vendor');
fs.mkdirSync(out, { recursive: true });
fs.copyFileSync(path.join(root, 'engine', 'core.js'), path.join(out, 'engine.js'));
const { catalogue, agency } = require(path.join(root, 'engine', 'test', 'fixture.js'));
fs.writeFileSync(path.join(out, 'demo-data.js'),
  '/* Generated by scripts/build-portal.js from engine/test/fixture.js. SAMPLE data only. */\n' +
  'window.DEMO_CATALOGUE = ' + JSON.stringify(catalogue, null, 1) + ';\n' +
  'window.DEMO_AGENCY = ' + JSON.stringify(agency) + ';\n');
console.log('portal/vendor updated');
